const DETAILS_OMITTED = '[details omitted]';
const MAX_LABEL_LENGTH = 2_048;
const HOSTED_LABEL_REDACTIONS = [
  /(?:https?|wss?):\/\/[^\s"'<>]+/gi,
  /\bBearer\s+[^\s,;"']+/gi,
  /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,
  /(?:[A-Z]:[\\/]|\/)(?:Users|home|private|tmp|var|opt|workspace|Volumes|root|mnt|srv)[\\/](?:[^\s"'<>]+ (?=[^\s"'<>]*[\\/]))*[^\s"'<>]+/gi,
  /\b[A-Z]:[\\/][^\s"'<>]+/gi,
  /\b[\w.-]{0,32}(?:token|secret|password|passwd|api[_-]?key)[\w.-]{0,32}["']?\s{0,3}[=:]\s{0,3}["']?[^\s,;"'<>]{1,256}/gi,
  /\b(?:sk-|sk_live_|sk_test_|rk_live_|rk_test_|sb_secret_|phx_|ghp_|gho_|ghs_|ghu_|github_pat_|glpat-|xox[abprs]-)[A-Za-z0-9_-]+/g,
  /\bnpm_[A-Za-z0-9]{36}\b/g,
  /\bAKIA[0-9A-Z]{16}\b/g,
  /\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g,
];

export const redactSensitiveText = (text: string): string =>
  HOSTED_LABEL_REDACTIONS.reduce(
    (current, pattern) => current.replace(pattern, '[redacted]'),
    text,
  );

export const hostedLogValues = (
  message: unknown,
  values: unknown[],
): unknown[] => {
  const label = typeof message === 'string' ? message : DETAILS_OMITTED;
  const redacted = redactSensitiveText(label).slice(0, MAX_LABEL_LENGTH);
  return [
    redacted,
    ...values.map((value) => {
      if (typeof value === 'boolean') return value;
      if (typeof value === 'number' && Number.isFinite(value)) return value;
      return DETAILS_OMITTED;
    }),
  ];
};
